// Fixed upstream flynn/noise v1.1.0 vectors (vectors.txt), not generated by
// the implementation under test. This checks both flights and both split keys.
func TestV2NoiseKnownAnswers(t *testing.T) {
	data, err := os.ReadFile("testdata/noise_nnpsk0.json")
	if err != nil {
		t.Fatal(err)
	}
	var vectors []map[string]string
	if err = json.Unmarshal(data, &vectors); err != nil {
		t.Fatal(err)
	}
	if len(vectors) != 8 {
		t.Fatal("missing suites")
	}
	for _, v := range vectors {
		t.Run(v["handshake"], func(t *testing.T) {
			dec := func(s string) []byte {
				b, e := hex.DecodeString(s)
				if e != nil {
					t.Fatal(e)
				}
				return b
			}
			cf := noiseAEADFunc{method: 1}
			if v["handshake"] == "Noise_NNpsk0_25519_ChaChaPoly_SHA256" {
				cf = noiseAEADFunc{method: 2}
			}
			cfg := noise.Config{CipherSuite: noise.NewCipherSuite(noise.DH25519, cf, noise.HashSHA256), Pattern: noise.HandshakeNN, PresharedKey: dec(v["preshared_key"]), PresharedKeyPlacement: 0, Prologue: dec(v["prologue"]), Initiator: true, Random: bytes.NewReader(dec(v["gen_init_ephemeral"]))}
			a, e := noise.NewHandshakeState(cfg)
			if e != nil {
				t.Fatal(e)
			}
			cfg.Initiator = false
			cfg.Random = bytes.NewReader(dec(v["gen_resp_ephemeral"]))
			b, e := noise.NewHandshakeState(cfg)
			if e != nil {
				t.Fatal(e)
			}
			first, _, _, e := a.WriteMessage(nil, dec(v["msg_0_payload"]))
			if e != nil || !bytes.Equal(first, dec(v["msg_0_ciphertext"])) {
				t.Fatal("first flight", e)
			}
			if _, _, _, e = b.ReadMessage(nil, first); e != nil {
				t.Fatal(e)
			}
			second, btx, brx, e := b.WriteMessage(nil, dec(v["msg_1_payload"]))
			if e != nil || !bytes.Equal(second, dec(v["msg_1_ciphertext"])) {
				t.Fatal("second flight", e)
			}
			_, atx, arx, e := a.ReadMessage(nil, second)
			if e != nil {
				t.Fatal(e)
			}
			for _, c := range []struct {
				tx, rx *noise.CipherState
				p, w   string
			}{{atx, btx, v["msg_2_payload"], v["msg_2_ciphertext"]}, {brx, arx, v["msg_3_payload"], v["msg_3_ciphertext"]}} {
				encrypted, e := c.tx.Encrypt(nil, nil, dec(c.p))
				if e != nil || !bytes.Equal(encrypted, dec(c.w)) {
					t.Fatal("split vector", e)
				}
				plain, e := c.rx.Decrypt(nil, nil, encrypted)
				if e != nil || !bytes.Equal(plain, dec(c.p)) {
					t.Fatal("split decrypt", e)
				}
			}
		})
	}
}

func TestV2PrologueAndHelloBounds(t *testing.T) {
	cfg := configFor(t, "")
	u := User{ID: 1, Key: testKey(2)}
	for _, mode := range []string{"prologue", "oversized-padding", "bad-ephemeral"} {
		t.Run(mode, func(t *testing.T) {
			s, _ := NewServer(cfg, []User{u})
			first, _ := firstFlight(t, cfg, u)
			switch mode {
			case "prologue":
				iv, _ := cfg.makeIV(1, s.users[1].KeyID, time.Now())
				copy(first, iv)
			case "oversized-padding":
				hs, _ := cfg.handshake(s.users[1].key, first[:IVSize], true)
				msg, _, _, _ := hs.WriteMessage(nil, make([]byte, 128))
				var buf bytes.Buffer
				_ = writeNoise(&buf, first[:IVSize], msg)
				first = buf.Bytes()
			case "bad-ephemeral":
				clear(first[IVSize+2 : IVSize+34])
			}
			conn := &memoryConn{input: bytes.NewReader(first)}
			if _, _, _, e := s.Accept(conn); e == nil || conn.output.Len() != 0 {
				t.Fatal("invalid hello answered", e)
			}
		})
	}
}

func TestV2RevocationDuringHandshake(t *testing.T) {
	cfg := configFor(t, "")
	u := User{ID: 1, Key: testKey(2)}
	s, _ := NewServer(cfg, []User{u})
	first, hs := firstFlight(t, cfg, u)
	a, b := net.Pipe()
	defer a.Close()
	defer b.Close()
	a.SetDeadline(time.Now().Add(time.Second))
	b.SetDeadline(time.Now().Add(time.Second))
	done := make(chan error, 1)
	go func() { _, _, _, e := s.Accept(b); done <- e }()
	if e := writeFull(a, first); e != nil {
		t.Fatal(e)
	}
	response, e := readNoise(a)
	if e != nil {
		t.Fatal(e)
	}
	_, tx, rx, e := hs.ReadMessage(nil, response)
	if e != nil {
		t.Fatal(e)
	}
	s.RemoveUser(1)
	stream := newStream(a, tx, rx, cfg, cfg.newPaddingAllowance())
	var addr bytes.Buffer
	_ = M.SocksaddrSerializer.WriteAddrPort(&addr, M.ParseSocksaddr("example.com:443"))
	_, _ = io.Copy(stream, &addr)
	if e = <-done; e == nil {
		t.Fatal("revoked in-flight user admitted")
	}
}

// Construct a PSK-authenticated first flight with a low-order public key,
// rather than merely damaging a tag. The responder's DH must reject it.
type lowOrderDH struct{ noise.DHFunc }

func (d lowOrderDH) GenerateKeypair(r io.Reader) (noise.DHKey, error) {
	k, e := d.DHFunc.GenerateKeypair(r)
	clear(k.Public)
	return k, e
}
func TestV2AuthenticatedLowOrderDHRejected(t *testing.T) {
	cfg := configFor(t, "")
	user := User{ID: 1, Key: testKey(2)}
	s, _ := NewServer(cfg, []User{user})
	rogue := *cfg
	rogue.suite = noise.NewCipherSuite(lowOrderDH{noise.DH25519}, noise.CipherAESGCM, noise.HashSHA256)
	first, _ := firstFlight(t, &rogue, user)
	conn := &memoryConn{input: bytes.NewReader(first)}
	if accepted, _, _, err := s.Accept(conn); err == nil || accepted != nil || conn.output.Len() != 0 {
		t.Fatal("low-order key admitted", err)
	}
}
func TestV2ReplayCacheExpiryAndCapacity(t *testing.T) {
	var c replayCache
	now := time.Unix(2000000000, 0)
	iv := make([]byte, IVSize)
	if !c.remember(iv, now) || c.remember(iv, now.Add(time.Minute)) {
		t.Fatal("duplicate replay")
	}
	if !c.remember(iv, now.Add(replayRetention+time.Second)) {
		t.Fatal("expired entry not reclaimed")
	}
	for i := 1; i < maxReplayEntries; i++ {
		binary.BigEndian.PutUint32(iv, uint32(i))
		if !c.remember(iv, now.Add(replayRetention+time.Second)) {
			t.Fatal("early capacity")
		}
	}
	binary.BigEndian.PutUint32(iv, uint32(maxReplayEntries))
	if c.remember(iv, now.Add(replayRetention+time.Second)) {
		t.Fatal("capacity bypass")
	}
}
